  "prediction_basis_card_ids": ["C01","C07","C14","C18","C23","C12","C32","C56"],
  "claims": [
    {
      "claim": "Measured absolute oral bioavailability in humans for structurally related amide/heteroaromatic drugs is predominantly above 20%: imidafenacin 57.8%, tolvaptan 56%, ACT-1004-1239 53%, lenvatinib in the order of 85%, and bromazepam 86%.",
      "card_ids": ["C01","C07","C14","C18","C23","C12"]
    },
    {
      "claim": "Venadaparib, the closest benzamide-indazole analog, showed good oral bioavailability in patients and 70.63% oral bioavailability in mice.",
      "card_ids": ["C32","C56"]
    },
    {
      "claim": "L3 oral exposure records for olaparib, a PARP inhibitor structurally related to venadaparib, show measurable dose-dependent Cmax and AUC after oral dosing in humans, consistent with oral absorption, but they do not provide F values.",
      "card_ids": ["C92","C97","C104","C107","C109","C119","C133","C136"]
    },
    {
      "claim": "Apatinib L2 records show human F of 10–20% and low dog F, indicating that the pyridine-amide class is not uniformly high-F; this weakens but does not overturn the overall supportive pattern.",
      "card_ids": ["C44","C58","C82","C89"]
    },
    {
      "claim": "No L3 record provides an affirmative threshold-relevant low-F outcome for the query or a close analog.",
      "card_ids": ["C92","C97","C104","C107","C109","C119","C133","C136"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": ["C92","C97","C104","C107","C109","C119","C133","C136","C91","C115"]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the query molecule.",
    "No human PK, solubility, or permeability data for the query under fasted conditions.",
    "L3 records provide only oral Cmax/AUC without IV comparators, so F cannot be derived from them.",
    "The closest benzamide-indazole analog, venadaparib, lacks a measured human absolute F value; only a mouse F of 70.63% is available.",
    "Apatinib's measured human F of 10–20% shows class variability, but query-specific first-pass, efflux, and dissolution behavior are not quantified.",
    "Fasted-state dissolution risk from high logD (4.64) is not experimentally quantified."
  ],
  "decision_summary": "Prediction high: multiple structurally related amide/heteroaromatic drugs have measured human F values of 53–86%, and the closest benzamide-indazole analog venadaparib is orally bioavailable (70.63% F in mice). L3 oral exposure records for olaparib and related compounds show measurable oral Cmax/AUC but no F values, so they do not overturn the prior decision; no affirmative threshold-relevant low-F evidence for the query. F >= 20% remains better supported."
}

